enum Weather {
  Sunny,
  Cloudy,
  Rainy(mm: Float64),
  Snowy(cm: Float64),
}

fn report(weather: Weather) -> Str {
  return match weather {
    Sunny => "Clear and bright",
    Cloudy => "Gray skies",
    Rainy(mm) => "Rain: " + " mm expected",
    Snowy(cm) => "Snow: " + " cm accumulated",
  };
}

fn main() -> Int {
  let today = Weather.Rainy(4.2);
  io.println(report(today));
  return 0;
}
